{
  "story": "Step through a Llama-style decoder block to see how token representations are transformed by normalization, attention, and feed-forward swiglu layers.",
  "aha": {
    "stateId": "s3",
    "observation": "RMSNorm preserves scale stability before attention computes semantic mixing."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Block Step",
      "options": ["Input", "RMSNorm 1", "Attention", "RMSNorm 2", "SwiGLU", "Residual Add"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Llama Decoder Block",
        "regions": [
          {
            "id": "r_input",
            "label": "Token Embeddings"
          },
          {
            "id": "r_norm1",
            "label": "RMSNorm 1"
          },
          {
            "id": "r_attn",
            "label": "Self-Attention"
          },
          {
            "id": "r_norm2",
            "label": "RMSNorm 2"
          },
          {
            "id": "r_mlp",
            "label": "SwiGLU MLP"
          }
        ],
        "states": [
          {
            "id": "s1",
            "label": "Input",
            "sentence": "Input token representations enter the decoder block.",
            "why": "Establishes starting vector state.",
            "active": ["r_input"],
            "calloutRegion": "r_input",
            "readouts": [
              {
                "id": "dim",
                "label": "Hidden Dim",
                "value": "4096"
              }
            ]
          },
          {
            "id": "s2",
            "label": "Norm 1",
            "sentence": "Pre-normalization stabilizes variance using RMSNorm.",
            "why": "Prevents exploding gradients before mixing.",
            "active": ["r_norm1"],
            "calloutRegion": "r_norm1",
            "readouts": [
              {
                "id": "rms",
                "label": "Variance",
                "value": "1.0"
              }
            ]
          },
          {
            "id": "s3",
            "label": "Attention",
            "sentence": "Rotary embeddings and grouped-query attention mix token contexts.",
            "why": "Core aha: captures token dependencies efficiently.",
            "active": ["r_attn"],
            "calloutRegion": "r_attn",
            "readouts": [
              {
                "id": "heads",
                "label": "Query Heads",
                "value": "32"
              }
            ]
          },
          {
            "id": "s4",
            "label": "Norm 2",
            "sentence": "A second RMSNorm prepares features for the feed-forward network.",
            "why": "Ensures stable scaling for the MLP.",
            "active": ["r_norm2"],
            "calloutRegion": "r_norm2",
            "readouts": [
              {
                "id": "rms2",
                "label": "Variance",
                "value": "1.0"
              }
            ]
          },
          {
            "id": "s5",
            "label": "SwiGLU",
            "sentence": "SwiGLU non-linearity expands and filters the feature dimension.",
            "why": "Enriches token representations.",
            "active": ["r_mlp"],
            "calloutRegion": "r_mlp",
            "readouts": [
              {
                "id": "mlp_dim",
                "label": "Intermediate",
                "value": "11008"
              }
            ]
          }
        ]
      }
    ]
  }
}
